<?php
require_once __DIR__.'/includes/functions.php';must_login();require_permission('agenda');check_csrf();require_once __DIR__.'/config/database.php';$error='';
if($_SESSION['user']['rol']==='Especialista'&&empty($_SESSION['user']['especialista_id'])){http_response_code(403);exit('Tu usuario no tiene un perfil de especialista vinculado.');}if($_SERVER['REQUEST_METHOD']==='POST')require_permission('agenda_write');
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='cancel'){try{$st=$pdo->prepare('UPDATE citas SET estado="Cancelada" WHERE id=? AND estado NOT IN ("Atendida","Cancelada")');$st->execute([(int)($_POST['id']??0)]);flash('Cita cancelada.');}catch(Throwable $e){flash('No se pudo cancelar la cita.','error');}go('agenda.php');}
if($_SERVER['REQUEST_METHOD']==='POST')try{$id=(int)($_POST['id']??0);$cliente=(int)($_POST['cliente_id']??0);$esp=(int)($_POST['especialista_id']??0);$serv=(int)($_POST['servicio_id']??0);$fecha=$_POST['fecha']??'';$hora=$_POST['hora_inicio']??'';$estado=$_POST['estado']??'Pendiente';$obs=trim($_POST['observaciones']??'');if(!$cliente||!$esp||!$serv||!valid_date($fecha)||!preg_match('/^\d{2}:\d{2}$/',$hora))throw new RuntimeException('Completa todos los datos de la cita.');if(!$id&&$fecha<date('Y-m-d'))throw new RuntimeException('No puedes registrar una cita en una fecha pasada.');if(!in_array($estado,['Pendiente','Confirmada','En atención','Atendida','Cancelada','No asistió'],true))throw new RuntimeException('Estado no válido.');if($estado==='Atendida'){$q=$pdo->prepare('SELECT COUNT(*) FROM atenciones WHERE cita_id=?');$q->execute([$id]);if(!$id||!(int)$q->fetchColumn())throw new RuntimeException('Registra la atención desde el módulo Atenciones para marcar la cita como atendida.');}
$q=$pdo->prepare('SELECT id FROM especialistas WHERE id=? AND estado="Activo"');$q->execute([$esp]);if(!$q->fetch())throw new RuntimeException('Selecciona un especialista activo.');$q=$pdo->prepare('SELECT duracion_minutos FROM servicios WHERE id=? AND estado="Activo"');$q->execute([$serv]);$dur=(int)$q->fetchColumn();if(!$dur)throw new RuntimeException('Selecciona un servicio activo.');$start=new DateTime($hora);$end=(clone $start)->modify("+$dur minutes");if($end->format('Y-m-d')!==$fecha)throw new RuntimeException('La cita debe terminar el mismo día.');$endTime=$end->format('H:i:s');$startTime=$start->format('H:i:s');
// Si el especialista tiene horarios configurados, la cita debe estar dentro de uno de ellos.
$weekday=(int)(new DateTime($fecha))->format('N');$q=$pdo->prepare('SELECT COUNT(*) FROM horarios_especialistas WHERE especialista_id=?');$q->execute([$esp]);$hasSchedule=(int)$q->fetchColumn()>0;if($hasSchedule){$q=$pdo->prepare('SELECT COUNT(*) FROM horarios_especialistas WHERE especialista_id=? AND dia_semana=? AND hora_inicio<=? AND hora_fin>=?');$q->execute([$esp,$weekday,$startTime,$endTime]);if(!(int)$q->fetchColumn())throw new RuntimeException('La cita está fuera del horario configurado para ese especialista.');}elseif($startTime<'07:00:00'||$endTime>'21:00:00')throw new RuntimeException('Sin horario personalizado, la atención permitida es de 07:00 a 21:00.');
// Si existen servicios asignados al especialista, solo se permiten los servicios asignados.
$q=$pdo->prepare('SELECT COUNT(*) FROM especialista_servicio WHERE especialista_id=?');$q->execute([$esp]);if((int)$q->fetchColumn()>0){$q=$pdo->prepare('SELECT COUNT(*) FROM especialista_servicio WHERE especialista_id=? AND servicio_id=?');$q->execute([$esp,$serv]);if(!(int)$q->fetchColumn())throw new RuntimeException('Ese servicio no está asignado al especialista seleccionado.');}
$pdo->beginTransaction();$lock=$pdo->prepare('SELECT id FROM especialistas WHERE id=? FOR UPDATE');$lock->execute([$esp]);if(!$lock->fetch())throw new RuntimeException('Especialista no encontrado.');$sql='SELECT COUNT(*) FROM citas WHERE especialista_id=? AND fecha=? AND estado NOT IN ("Cancelada","No asistió") AND hora_inicio < ? AND hora_fin > ?'.($id?' AND id<>?':'');$params=[$esp,$fecha,$endTime,$startTime];if($id)$params[]=$id;$q=$pdo->prepare($sql);$q->execute($params);if((int)$q->fetchColumn())throw new RuntimeException('El especialista ya tiene una cita en ese horario.');
if($id){$q=$pdo->prepare('UPDATE citas SET cliente_id=?,especialista_id=?,servicio_id=?,fecha=?,hora_inicio=?,hora_fin=?,estado=?,observaciones=? WHERE id=?');$q->execute([$cliente,$esp,$serv,$fecha,$startTime,$endTime,$estado,$obs,$id]);}else{$q=$pdo->prepare('INSERT INTO citas(cliente_id,especialista_id,servicio_id,fecha,hora_inicio,hora_fin,estado,observaciones) VALUES(?,?,?,?,?,?,?,?)');$q->execute([$cliente,$esp,$serv,$fecha,$startTime,$endTime,$estado,$obs]);}$pdo->commit();flash('Cita guardada. Duración: '.$dur.' minutos.');go('agenda.php');
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof PDOException?'No se pudo guardar la cita. Revisa los datos.':$e->getMessage();}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM citas WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$clientes=$pdo->query('SELECT id,nombres,apellidos FROM clientes ORDER BY nombres')->fetchAll();$especialistas=$pdo->query("SELECT id,nombres,apellidos FROM especialistas WHERE estado='Activo' ORDER BY nombres")->fetchAll();$servicios=$pdo->query("SELECT id,nombre,duracion_minutos,precio FROM servicios WHERE estado='Activo' ORDER BY nombre")->fetchAll();$rows=($_SESSION['user']['rol']==='Especialista'&& !empty($_SESSION['user']['especialista_id']))?$pdo->prepare('SELECT c.*,CONCAT(cl.nombres," ",cl.apellidos) cliente,CONCAT(e.nombres," ",e.apellidos) especialista,s.nombre servicio FROM citas c JOIN clientes cl ON cl.id=c.cliente_id JOIN especialistas e ON e.id=c.especialista_id JOIN servicios s ON s.id=c.servicio_id WHERE c.especialista_id=? ORDER BY c.fecha DESC,c.hora_inicio DESC LIMIT 250'):$pdo->query('SELECT c.*,CONCAT(cl.nombres," ",cl.apellidos) cliente,CONCAT(e.nombres," ",e.apellidos) especialista,s.nombre servicio FROM citas c JOIN clientes cl ON cl.id=c.cliente_id JOIN especialistas e ON e.id=c.especialista_id JOIN servicios s ON s.id=c.servicio_id ORDER BY c.fecha DESC,c.hora_inicio DESC LIMIT 250');if($rows instanceof PDOStatement){if($_SESSION['user']['rol']==='Especialista')$rows->execute([(int)$_SESSION['user']['especialista_id']]);$rows=$rows->fetchAll();}$title='Agenda de citas';require __DIR__.'/includes/header.php';?>
<div class="heading"><div><span class="eyebrow">PROGRAMACIÓN</span><h1>Agenda de citas</h1><p class="muted">Control de horarios, disponibilidad y conflictos entre citas.</p></div></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?>
<div class="split"><?php if(in_array($_SESSION['user']['rol'],['Administrador','Recepcionista'],true)):?><section class="panel form-panel"><h2><?=$edit?'Editar cita':'Programar cita'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="form-grid"><label class="field"><span>Cliente</span><select name="cliente_id" required><option value="">Seleccionar</option><?php foreach($clientes as $x):?><option value="<?=$x['id']?>" <?=((int)($edit['cliente_id']??0)===(int)$x['id'])?'selected':''?>><?=e($x['nombres'].' '.$x['apellidos'])?></option><?php endforeach;?></select></label><label class="field"><span>Especialista</span><select name="especialista_id" required><option value="">Seleccionar</option><?php foreach($especialistas as $x):?><option value="<?=$x['id']?>" <?=((int)($edit['especialista_id']??0)===(int)$x['id'])?'selected':''?>><?=e($x['nombres'].' '.$x['apellidos'])?></option><?php endforeach;?></select></label><label class="field"><span>Servicio</span><select name="servicio_id" required><option value="">Seleccionar</option><?php foreach($servicios as $x):?><option value="<?=$x['id']?>" <?=((int)($edit['servicio_id']??0)===(int)$x['id'])?'selected':''?>><?=e($x['nombre'].' · '.$x['duracion_minutos'].' min · '.money($x['precio']))?></option><?php endforeach;?></select></label><label class="field"><span>Fecha</span><input type="date" name="fecha" min="<?=date('Y-m-d')?>" value="<?=e($edit['fecha']??date('Y-m-d'))?>" required></label><label class="field"><span>Hora de inicio</span><input type="time" name="hora_inicio" value="<?=e(isset($edit['hora_inicio'])?substr($edit['hora_inicio'],0,5):'09:00')?>" required></label><label class="field"><span>Estado</span><select name="estado"><?php foreach(['Pendiente','Confirmada','En atención','Atendida','Cancelada','No asistió'] as $st):?><option <?=($edit['estado']??'Pendiente')===$st?'selected':''?>><?=e($st)?></option><?php endforeach;?></select></label><label class="field full"><span>Observaciones</span><textarea name="observaciones" rows="2"><?=e($edit['observaciones']??'')?></textarea></label></div><div class="actions"><button class="btn">Guardar cita</button><?php if($edit):?><a class="btn ghost" href="agenda.php">Cancelar edición</a><?php endif;?></div></form><p class="muted">Configura la disponibilidad en <a href="horarios.php">Horarios de especialistas</a>.</p></section><?php endif;?>
<section class="panel table-panel"><h2>Citas registradas</h2><div class="tablewrap"><table><thead><tr><th>Fecha</th><th>Hora</th><th>Cliente</th><th>Servicio</th><th>Especialista</th><th>Estado</th><?php if($_SESSION['user']['rol']!=='Especialista'):?><th>Acciones</th><?php endif;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['fecha'])?></td><td><?=e(substr($r['hora_inicio'],0,5).' - '.substr($r['hora_fin'],0,5))?></td><td><?=e($r['cliente'])?></td><td><?=e($r['servicio'])?></td><td><?=e($r['especialista'])?></td><td><span class="badge"><?=e($r['estado'])?></span></td><?php if($_SESSION['user']['rol']!=='Especialista'):?><td class="row-actions"><a href="agenda.php?edit=<?=$r['id']?>">Editar</a><?php if(!in_array($r['estado'],['Atendida','Cancelada'],true)):?><form method="post" onsubmit="return confirm('¿Cancelar esta cita?')"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="cancel"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="link danger">Cancelar</button></form><?php endif;?></td><?php endif;?></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="<?=($_SESSION['user']['rol']==='Especialista'?6:7)?>" class="empty">No hay citas registradas.</td></tr><?php endif;?></tbody></table></div></section></div><?php require __DIR__.'/includes/footer.php';?>
